/// Walk one directory segment beneath a trusted canonical parent: if the
/// segment exists it must be a real directory whose canonical path stays
/// beneath `parent` (never a symlink); if absent it is created. Returns the
/// canonical path of the trusted segment so all derived paths inherit the
/// trusted root. Used to harden `.sea-forge` and `imported` against
/// pre-existing symlink escapes at import time.
fn ensure_trusted_dir(parent: &Path, name: &str) -> Result<PathBuf, ForgeError> {
    let candidate = parent.join(name);
    match fs::symlink_metadata(&candidate) {
        Ok(md) if md.file_type().is_symlink() => Err(ForgeError::UnsafePath(format!(
            "{name} is a symlink"
        ))),
        Ok(md) if !md.is_dir() => Err(ForgeError::UnsafePath(format!(
            "{name} is not a directory"
        ))),
        Ok(_) => {
            let canonical = candidate
                .canonicalize()
                .map_err(|e| ForgeError::io(format!("canonicalize {name}"), e))?;
            if !canonical.starts_with(parent) {
                return Err(ForgeError::UnsafePath(format!("{name} escapes trust root")));
            }
            Ok(canonical)
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            fs::create_dir_all(&candidate)
                .map_err(|e| ForgeError::io(format!("create {name}"), e))?;
            candidate
                .canonicalize()
                .map_err(|e| ForgeError::io(format!("canonicalize new {name}"), e))
        }
        Err(e) => Err(ForgeError::io(format!("inspect {name}"), e)),
    }
}

