/// Append a tar entry using a raw path, bypassing higher-level sanitizing so a
/// hostile `path` string is preserved verbatim in the archive. Uses
/// `tar::Builder::append_data` so paths that exceed the 100-byte header name
/// field (or that `Header::set_path` rejects) are carried by a GNU `././@LongLink`
/// extension entry instead of being silently substituted with a placeholder.
fn append_raw(builder: &mut tar::Builder<&mut Vec<u8>>, path: &str, data: &[u8]) {
    let mut hdr = tar::Header::new_gnu();
    hdr.set_size(data.len() as u64);
    hdr.set_mode(0o644);
    builder
        .append_data(&mut hdr, path, data)
        .expect("append_data must preserve the hostile name via GNU longname");
}

